import os
os.environ['MPLCONFIGDIR']='/tmp/probe-matplotlib'
import json,gzip,collections,html,hashlib
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parent;O=R/'results'
def read(p):
 with gzip.open(p,'rt') if str(p).endswith('.gz') else open(p) as f:return json.load(f)
rows=read(O/'cells.json');summary=read(O/'summary.json');ds=read(O/'delta_summary.json');traces=read(O/'tradeoff_points.json.gz')
C=['baseline','saliency','nearest'];A=['baseline','nearest','saliency'];COL={'baseline':'#64748b','saliency':'#d97706','nearest':'#1676c5'};LABEL={'baseline':'No explanation','saliency':'Saliency','nearest':'1 NN','average_of_three':'Mean across three tuning sources'}
MODELS=['qwen','gemma','mistral','olmo','glm','qwen122','claude4.5-sonnet','claude4.8-opus','gpt-4o','gpt-astra']
agg=collections.defaultdict(list)
for r in traces:
 for scope in ([r['scope'],'combined'] if r['scope']!='common_valid' else [r['scope']]):
  agg[scope,r['anchor'],r['condition'],r['beta_index']].append((r['recall']*100,r['precision']*100))
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.16})
for scope,name in [('combined','frontier_by_tuning_source'),('common_valid','frontier_common_valid')]:
 fig,axs=plt.subplots(1,3,figsize=(16,5.8));fig.subplots_adjust(left=.055,right=.99,top=.79,bottom=.24,wspace=.25)
 for ax,anchor in zip(axs,A):
  for c in C:
   xy=np.array([np.mean(agg[scope,anchor,c,i],axis=0) for i in range(41)]);ax.plot(xy[:,0],xy[:,1],color=COL[c],lw=2,label=LABEL[c]);ax.scatter(xy[20,0],xy[20,1],marker='*',s=200,color=COL[c],edgecolors='white',lw=.7,zorder=5)
  ax.set_title('Tune on '+LABEL[anchor]+' only\nFreeze both cutoffs across all conditions',fontsize=12);ax.set_xlabel('Mean test recall (%)');ax.set_ylabel('Mean test precision (%)')
 fig.suptitle('Same thresholds within every comparison: three validation tuning sources',fontsize=16)
 fig.text(.5,.12,'★ Threshold pair maximising the tuning source’s validation F1. Lines vary its validation Fβ objective.',ha='center',fontsize=10)
 fig.text(.5,.085,'500 combinations. '+('Original local/API evaluation scopes.' if scope=='combined' else 'Identical valid cases across all ten judges.')+' No test-based threshold selection.',ha='center',fontsize=10)
 fig.legend(*axs[0].get_legend_handles_labels(),loc='lower center',bbox_to_anchor=(.5,.01),ncol=3,frameon=False)
 for ext in ['png','pdf','svg']:fig.savefig(O/(name+'.'+ext),dpi=180,facecolor='white')
 plt.close(fig)

# Compact embedded data, preserving exact cutoffs in the table/download.
key=lambda r:tuple(r[k] for k in ['scope','model','backbone','dataset','anchor','condition'])
records={key(r):{**{k:r[k] for k in ['scope','model','backbone','dataset','anchor','condition','probe_threshold','judge_threshold','test_n','validation_n','test_referred','test_rejected']},**{k:round(r[k],9) for k in ['precision','recall','f1','accuracy']},'trace':[]} for r in rows}
for r in traces:records[key(r)]['trace'].append([round(r['recall'],7),round(r['precision'],7)])
payload=json.dumps(list(records.values()),separators=(',',':')).replace('</','<\\/')
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transfer identical thresholds across explanations</title><style>body{font:15px/1.5 system-ui;color:#1d3045;background:#f3f6fa;margin:0}main{max-width:1450px;padding:30px;margin:auto}h1{font-size:29px}.card{background:white;border:1px solid #dce4ed;border-radius:12px;padding:20px;margin:18px 0}.controls{display:flex;gap:20px;flex-wrap:wrap}label{display:grid;gap:5px}select{padding:8px;background:white;border:1px solid #aebdcc;border-radius:4px;font:inherit}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{padding:9px;border-bottom:1px solid #dce4ed;text-align:right;white-space:nowrap}td:first-child,th:first-child{text-align:left}th{background:#eef3f9;font-size:13px}.scroll{overflow:auto}.small{font-size:13px;color:#536579}.zero{background:#ffe4d6;color:#8d300d}svg{width:100%;height:auto}a{color:#1266ad}summary{cursor:pointer;font-weight:bold}.average{background:#edf5fc;font-weight:600}</style></head><body><main>
<h1>Choose thresholds on one condition, then freeze them for all three</h1>
<p>For each judge × backbone × dataset, jointly choose the probe and judge cutoffs on <b>control validation F1</b>, apply both unchanged to all conditions, then repeat with <b>NN</b> and <b>saliency</b> as the tuning source. Test labels never select thresholds. This controls the threshold difference within every comparison.</p>
<div class="card controls"><label>Population<select id="scope"><option value="combined">All500 combinations: original scopes</option><option value="common_valid">Same valid cases across all judges</option><option value="local_full">Local full-test estimates</option><option value="api_matched">API available-case estimates</option></select></label><label>Judge<select id="model"><option value="ALL">All</option></select></label><label>Backbone<select id="backbone"><option value="ALL">All</option></select></label><label>Dataset<select id="dataset"><option value="ALL">All</option></select></label></div>
<div class="card"><h2>Test F1 and within-threshold differences</h2><p id="support" class="small"></p><div id="matrix" class="scroll"></div><p class="small">Scores are percentages; differences are percentage points. The last row averages each within-source difference equally across the three tuning sources, then across combinations. It is a sensitivity summary using the same cases three times, not three independent experiments or a deployable average threshold.</p></div>
<div class="card"><h2>Precision, recall and accuracy</h2><div id="metrics" class="scroll"></div></div>
<div class="card"><h2>Transferred precision–recall trade-offs on test</h2><label>Tuning source<select id="anchor"><option value="baseline">No explanation</option><option value="nearest">1 NN</option><option value="saliency">Saliency</option></select></label><p class="small">Grey: control. Orange: saliency. Blue: NN. Stars mark the selected validation-F1 pair. Curves vary the selected source's validation Fβ objective; the same threshold pair is applied to every condition at each point. These are transferred trade-offs, not independently optimised explanation frontiers.</p><svg id="chart" viewBox="0 0 1000 540"></svg></div>
<div class="card"><h2>Average differences by judge</h2><p class="small">Averages equally across all three tuning sources, using the selected population/backbone/dataset. The judge filter above does not restrict this comparison.</p><div id="judges" class="scroll"></div></div>
<div class="card"><h2>Actual shared thresholds</h2><p class="small">Each row's pair is applied unchanged to control, saliency and NN. Probe scale0–1; judge scale0–100. Zero judge cutoffs are highlighted. Full precision retained.</p><div class="scroll" style="max-height:450px" id="thresholds"></div></div>
<details class="card"><summary>Methods and verification</summary><p>The original full validation grid and frozen highest-probe-then-highest-judge tie rule are reused. All3,000 diagonal condition cells are replayed against the previous independent-tuning analysis (original and common-valid scopes). Every transferred comparison verifies identical thresholds, identical referral sets, and identical final predictions whenever the selected judge cutoff is zero. β=1 is checked against each F1-optimal pair.</p><p>All means weight backbone–judge–dataset combinations equally. Original design weights are retained. Local estimates use exact full-test population totals; API estimates condition on valid answers across all three conditions for that model. The primary500-cell average mixes those scopes; the common-valid view uses identical retained cases across all judges. This does not resolve non-random API missingness. Results are point estimates, not significance claims. The already inspected test set makes this a follow-up analysis.</p><p>Each of the500 primary combinations contributes three tuning sources and three evaluated conditions. Averaging the three sources does not triple the independent sample size. “No effect” in a zero-cutoff cell follows from bypassing all judge scores; these cells remain in the analysis. Fixed50/50 results remain unchanged in the preceding report. No new model inference, training, or mechanism annotation has occurred.</p></details>
<div class="card"><h2>Downloads</h2><p><a href="summary.csv">Summary CSV</a> · <a href="delta_summary.csv">Mean differences CSV</a> · <a href="cells.csv">Every transferred result</a> · <a href="thresholds.csv">All selected threshold pairs</a> · <a href="frontier_by_tuning_source.pdf">Three-source frontier PDF</a> · <a href="../PROTOCOL.json">Protocol</a> · <a href="COMPLETED.json">Verification</a></p></div>
</main><script>const D=__DATA__,C=['baseline','saliency','nearest'],A=['baseline','nearest','saliency'],N={baseline:'No explanation',saliency:'Saliency',nearest:'1 NN',average:'Mean across3 sources'},COL={baseline:'#64748b',saliency:'#d97706',nearest:'#1676c5'};const $=id=>document.getElementById(id),avg=a=>a.reduce((s,x)=>s+x,0)/a.length,pct=x=>(x*100).toFixed(3),delta=x=>(x>=0?'+':'')+(x*100).toFixed(3);for(const k of ['model','backbone','dataset'])for(const v of [...new Set(D.map(r=>r[k]))]){const o=document.createElement('option');o.value=v;o.textContent=v;$(k).appendChild(o)}function filter(ignoreModel=false){const scope=$('scope').value;return D.filter(r=>(scope==='combined'?r.scope!=='common_valid':r.scope===scope)&&['model','backbone','dataset'].every(k=>(ignoreModel&&k==='model')||$(k).value==='ALL'||r[k]===$(k).value))}function means(rr,a,c,k){return avg(rr.filter(r=>r.condition===c&&(a==='average'||r.anchor===a)).map(r=>r[k]))}
function plot(rr){rr=rr.filter(r=>r.anchor===$('anchor').value);if(!rr.length){$('chart').innerHTML='';return}const lines=C.map(c=>{let q=rr.filter(r=>r.condition===c);return {c,p:Array.from({length:41},(_,i)=>[avg(q.map(r=>r.trace[i][0])),avg(q.map(r=>r.trace[i][1]))])}}),pts=lines.flatMap(l=>l.p),xmin=Math.max(0,Math.min(...pts.map(p=>p[0]))-.025),xmax=Math.min(1,Math.max(...pts.map(p=>p[0]))+.025),ymin=Math.max(0,Math.min(...pts.map(p=>p[1]))-.025),ymax=Math.min(1,Math.max(...pts.map(p=>p[1]))+.025),X=x=>85+865*(x-xmin)/(xmax-xmin||.01),Y=y=>455-415*(y-ymin)/(ymax-ymin||.01);let s='<rect width="1000" height="540" fill="white"/>';for(let i=0;i<=5;i++){let x=xmin+(xmax-xmin)*i/5,y=ymin+(ymax-ymin)*i/5;s+=`<path d="M${X(x)} 40V455 M85 ${Y(y)}H950" stroke="#e1e7ef"/><text x="${X(x)}" y="480" text-anchor="middle">${(100*x).toFixed(1)}</text><text x="75" y="${Y(y)+5}" text-anchor="end">${(100*y).toFixed(1)}</text>`}for(const l of lines){s+=`<polyline fill="none" stroke="${COL[l.c]}" stroke-width="2.5" points="${l.p.map(p=>X(p[0])+','+Y(p[1])).join(' ')}"/>`;l.p.forEach((p,i)=>s+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="2.5" fill="${COL[l.c]}"><title>${N[l.c]}: recall ${pct(p[0])}, precision ${pct(p[1])}; beta ${(10**(-1+i/20)).toPrecision(3)}</title></circle>`);s+=`<text x="${X(l.p[20][0])}" y="${Y(l.p[20][1])+9}" text-anchor="middle" font-size="30" fill="${COL[l.c]}" stroke="white" stroke-width=".6">★</text>`}s+='<text x="520" y="520" text-anchor="middle">Test recall (%)</text><text transform="translate(24 250) rotate(-90)" text-anchor="middle">Test precision (%)</text>';$('chart').innerHTML=s}
function update(){const rr=filter();if(!rr.length){for(const id of ['matrix','metrics','judges','thresholds','chart'])$(id).innerHTML='';$('support').textContent='No combinations match these filters.';return}let n=rr.length/9;$('support').textContent=`${n} combinations. Each tuning source uses the same three conditions and retained test cases. Up to500 validation and500 test cases per backbone–dataset pair before API exclusions.`;let t='<table><tr><th>Tune thresholds on</th><th>Control F1</th><th>Saliency F1</th><th>NN F1</th><th>NN − control</th><th>Saliency − control</th><th>NN − saliency</th></tr>';for(const a of [...A,'average']){let v=C.map(c=>means(rr,a,c,'f1'));t+=`<tr class="${a==='average'?'average':''}"><td>${N[a]}</td>${v.map(x=>'<td>'+pct(x)+'</td>').join('')}<td>${delta(v[2]-v[0])}</td><td>${delta(v[1]-v[0])}</td><td>${delta(v[2]-v[1])}</td></tr>`}$('matrix').innerHTML=t+'</table>';let m='<table><tr><th>Tuning source / condition</th><th>Precision</th><th>Recall</th><th>Accuracy</th></tr>';for(const a of [...A,'average'])for(const c of C)m+=`<tr><td>${N[a]} / ${N[c]}</td>${['precision','recall','accuracy'].map(k=>'<td>'+pct(means(rr,a,c,k))+'</td>').join('')}</tr>`;$('metrics').innerHTML=m+'</table>';let all=filter(true),j='<table><tr><th>Judge</th><th>NN − control F1</th><th>Saliency − control F1</th><th>NN − saliency F1</th><th>NN − control precision</th><th>NN − control recall</th><th>NN − control accuracy</th></tr>';for(const model of [...new Set(all.map(r=>r.model))]){let q=all.filter(r=>r.model===model),f=C.map(c=>means(q,'average',c,'f1'));j+=`<tr><td>${model}</td><td>${delta(f[2]-f[0])}</td><td>${delta(f[1]-f[0])}</td><td>${delta(f[2]-f[1])}</td>${['precision','recall','accuracy'].map(k=>'<td>'+delta(means(q,'average','nearest',k)-means(q,'average','baseline',k))+'</td>').join('')}</tr>`}$('judges').innerHTML=j+'</table>';let th='<table><tr><th>Judge</th><th>Backbone</th><th>Dataset</th><th>Tune on</th><th>Shared probe cutoff</th><th>Shared judge cutoff</th></tr>';for(const r of rr.filter(r=>r.condition==='baseline'))th+=`<tr><td>${r.model}</td><td>${r.backbone}</td><td>${r.dataset}</td><td>${N[r.anchor]}</td><td>${r.probe_threshold}</td><td class="${r.judge_threshold===0?'zero':''}">${r.judge_threshold}</td></tr>`;$('thresholds').innerHTML=th+'</table>';plot(rr)}for(const k of ['scope','model','backbone','dataset','anchor'])$(k).addEventListener('change',update);update();</script></body></html>'''
(O/'report.html').write_text(page.replace('__DATA__',payload))
(O/'REPORT_VERIFIED.json').write_text(json.dumps({'records':len(records),'outputs':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [O/'report.html',O/'frontier_by_tuning_source.png',O/'frontier_common_valid.png',Path(__file__)]}},indent=2))
print('Report ready',O/'report.html')
